import json

# Correspondences supported by the unmasked examples:
# *dikiʔ > takiʔ; *bəsey > pathey; *paday > patày; *bara > pirà.
proto = "dəpa"
evidence = [
    ("d", "t", "*dikiʔ", "takiʔ"),
    ("ə", "a", "*bəsey", "pathey"),
    ("p", "p", "*paday", "patày"),
    ("final a", "à", "*bara", "pirà"),
]

result = []
for i, sound in enumerate(proto):
    if i == 0 and sound == "d":
        result.append("t")
    elif sound == "ə":
        result.append("a")
    elif sound == "p":
        result.append("p")
    elif i == len(proto) - 1 and sound == "a":
        result.append("à")
    else:
        raise ValueError("The given correspondences do not settle the result")

print(json.dumps({
    "final_answer": "".join(result),
    "evidence": [f"{source} > {reflex}" for _, _, source, reflex in evidence]
