from fractions import Fraction as F

# Laurent polynomials in z = exp(s), with exact rational coefficients.
def add(a, b):
    r = dict(a)
    for k, v in b.items():
        r[k] = r.get(k, F(0)) + v
    return {k: v for k, v in r.items() if v}

def scale(a, c):
    return {k: v * c for k, v in a.items() if v * c}

def deriv(a):
    return {k: k * v for k, v in a.items() if k * v}

def mul(a, b):
    r = {}
    for i, x in a.items():
        for j, y in b.items():
            r[i + j] = r.get(i + j, F(0)) + x * y
    return {k: v for k, v in r.items() if v}

def equal(a, b):
    return add(a, scale(b, -1)) == {}

def at_one(a):
    return sum(a.values(), F(0))

def show(a):
    if not a:
        return "0"
    return " + ".join(
        f"{v}*z^{k}" for k, v in sorted(a.items(), reverse=True)
    )

zero = {}
one = {0: F(1)}
z = {1: F(1)}
zinv = {-1: F(1)}

# Each option is represented as x=tau*X(z), y=tau*Y(z), u=tau^2*U(z).
options = {
    1: (
        add(scale(z, 3), {0: F(-3)}),
        scale(add(zinv, one), F(1, 2)),
        {-2: F(1)},
    ),
    2: (
        add(scale(z, 2), {0: F(-2)}),
        add({2: F(2)}, {0: F(-1)}),
        add({0: F(1, 2)}, {-2: F(1, 2)}),
    ),
    3: (
        add(scale(z, 2), {0: F(-2)}),
        scale(add(z, one), F(1, 2)),
        {2: F(1)},
    ),
    4: (
        add(zinv, {0: F(-1)}),
        add(scale(zinv, F(-2)), {0: F(3)}),
        add({-2: F(2)}, {0: F(-1)}),
    ),
}

def verify(option):
    X, Y, U = option
    # Charpit gives q = dx/ds divided by tau and p = dy/ds divided by tau.
    q = deriv(X)
    p = deriv(Y)

    checks = {
        "initial x=0": at_one(X) == 0,
        "initial y=tau": at_one(Y) == 1,
        "initial u=tau^2": at_one(U) == 1,
        "initial p=tau/2": at_one(p) == F(1, 2),
        "initial q=2*tau": at_one(q) == 2,
        "PDE p*q=u": equal(mul(p, q), U),
        "Charpit p'=p": equal(deriv(p), p),
        "Charpit q'=q": equal(deriv(q), q),
        "Charpit u'=2u": equal(deriv(U), scale(U, 2)),
    }
    return checks, p, q

print("Charpit equations: x'=q, y'=p, u'=2pq, p'=p, q'=q.")
print("Initial data imply q(0)=2*tau and p(0)=tau/2.")
print("Exact coefficient checks for all four options:")

all_pass = {}
for number, option in options.items():
    checks, p, q = verify(option)
    all_pass[number] = all(checks.values())
    print(f"\nOption {number}: p/tau={show(p)}, q/tau={show(q)}")
    for name, passed in checks.items():
        print(f"  {name}: {'PASS' if passed else 'FAIL'}")

print("\nIndependently integrated result:")
print("  x = 2*tau*(exp(s)-1)")
print("  y = tau*(exp(s)+1)/2")
print("  u = tau^2*exp(2*s)")
print(f"Option 3 passes every exact check: {all_pass[3]}")
print(f"Submitted answer (option 1) passes every exact check: {all_pass[1]}")
print("CHECK PASS" if all_pass[3] and not all_pass[1] else "CHECK FAIL")
