import json

animals = [
    "bee", "badger", "frog", "snake", "seahorse", "vampire", "swan",
    "beaver", "ostrich", "dove", "woodpecker", "emperor", "monkey",
    "stork", "beetle", "goat", "ant", "flamingo", "dinosaur", "zebra",
    "dragonfly", "fangtooth", "finch", "king", "pigeon", "peafowl",
    "rhino", "bison", "dove", "dragon"
]

# Literals are (subject, relation, object, is_positive).
facts = {
    ("bee", "card_color", "blue", True),
    ("frog", "card_color", "yellow", True),
    ("frog", "has_spinach", "", True),
    ("snake", "reduced_work_hours", "", True),
    ("bee", "tears_down_castle", "badger", False),
    ("seahorse", "creates_castle", "vampire", False),
}
derived_by = {}

def add(literal, rule):
    if literal not in facts:
        facts.add(literal)
        derived_by[literal] = rule
        return True
    return False

def has(subject, relation, obj="", positive=True):
    return (subject, relation, obj, positive) in facts

# Primary colors use the stipulated RGB definition. An explicit yellow card
# is not primary; a blue card is primary.
primary_colors = {"red", "green", "blue"}
frog_color = next(
    (obj for subj, rel, obj, pos in facts
     if subj == "frog" and rel == "card_color" and pos),
    None
)
frog_has_primary_card = frog_color in primary_colors
frog_has_leafy_green_vegetable = has("frog", "has_spinach")

for _ in range(30):
    changed = False

    # Rule 5
    if has("bee", "tears_down_castle", "badger", False):
        changed |= add(("bee", "refuses_help", "badger", True), "Rule5")

    # Rule 19
    for x in animals:
        if has(x, "refuses_help", "badger", True):
            changed |= add((x, "shouts_at", "dragonfly", True), "Rule19")

    # Rule 20
    for x in animals:
        if has(x, "shouts_at", "dragonfly", True):
            changed |= add((x, "wants_to_see", "fangtooth", True), "Rule20")

    # Rule 14
    for x in animals:
        if has(x, "wants_to_see", "fangtooth", True):
            changed |= add((x, "shouts_at", "beetle", False), "Rule14")

    # Rule 23, then Rule 2
    if has("snake", "reduced_work_hours", "", True):
        changed |= add(("snake", "tears_down_castle", "dove", True), "Rule23")
    if any(has(x, "tears_down_castle", "dove", True) for x in animals):
        changed |= add(("woodpecker", "takes_over", "emperor_of_monkey", True), "Rule2")

    # Rule 13, then Rule 17
    if any(has(x, "takes_over", "emperor_of_monkey", True) for x in animals):
        changed |= add(("bee", "refuses_help", "dinosaur", False), "Rule13")
    for x in animals:
        if has(x, "refuses_help", "dinosaur", False):
            changed |= add((x, "reveals_secret_to", "zebra", True), "Rule17")

    # Rule 18
    for x in animals:
        if (has(x, "shouts_at", "beetle", False)
                and has(x, "reveals_secret_to", "zebra", True)):
            changed |= add((x, "trades_piece_with", "stork", False), "Rule18")

    # Rule 21. Spinach is the stated leafy green vegetable.
    if frog_has_leafy_green_vegetable:
        changed |= add(("frog", "destroys_wall_built_by", "swan", True), "Rule21")

    # Rule 16's explicit primary-color antecedent is false for yellow.
    if frog_has_primary_card:
        changed |= add(("frog", "destroys_wall_built_by", "swan", False), "Rule16")

    # Rule 24
    if has("frog", "destroys_wall_built_by", "swan", True):
        changed |= add(("swan", "shouts_at", "peafowl", True), "Rule24")

    # Rule 12, then Rule 6. Rule 24 is preferred over Rule 6 when both apply.
    for x in animals:
        if has(x, "creates_castle", "vampire", False):
            changed |= add((x, "enjoys_companionship_of", "ant", True), "Rule12")
    if any(has(x, "enjoys_companionship_of", "ant", True) for x in animals):
        if not has("frog", "destroys_wall_built_by", "swan", True):
            changed |= add(("swan", "shouts_at", "peafowl", False), "Rule6")

    # Rule 22, Rule 1, and Rule 7
    for x in animals:
        if has(x, "shouts_at", "peafowl", True):
            changed |= add((x, "shouts_at", "beaver", True), "Rule22")
    for x in animals:
        if has(x, "shouts_at", "beaver", True):
            changed |= add((x, "unites_with", "ostrich", True), "Rule1")
    if any(has(x, "unites_with", "ostrich", True) for x in animals):
        changed |= add(("beetle", "trades_piece_with", "stork", True), "Rule7")

    # Rule 4, then Rule 10
    if (has("bee", "trades_piece_with", "stork", False)
            and has("beetle", "trades_piece_with", "stork", True)):
        changed |= add(("stork", "wants_to_see", "goat", True), "Rule4")
    if any(has(x, "wants_to_see", "goat", True) for x in animals):
        changed |= add(("finch", "captures", "king_of_pigeon", False), "Rule10")

    if not changed:
        break

positive_query = ("finch", "captures", "king_of_pigeon", True)
negative_query = ("finch", "captures", "king_of_pigeon", False)

if negative_query in facts and positive_query not in facts:
    answer = "disproved"
elif positive_query in facts and negative_query not in facts:
    answer = "proved"
else:
    answer = "unknown"

evidence = [
    "Rule23: snake reduced work hours -> snake tears down the dove's castle",
    "Rule2: this triggers woodpecker taking over the monkey's emperor",
    "Rules13, 17, 18: bee does not refuse dinosaur help -> reveals secret to zebra; with Rule14, bee does not trade with stork",
    "Rules21 and 24: frog's spinach -> destroys the swan's wall -> swan shouts at peafowl",
    "Rules22, 1, 7: swan shouts at beaver -> unites with ostrich -> beetle trades with stork",
    "Rule4: bee does not trade and beetle trades with stork -> stork wants to see the goat",
    "Rule10: an animal wants to see the goat -> finch does not capture the pigeon's king",
]
print(json.dumps({"final_answer": answer, "evidence": evidence}, separators=(",", ":")))
