import itertools
import json

# Model the practical interpretation as requiring both the availability of
# the two alternatives and the ability to choose between them.
# d = Confucius is demanding; v = both kinds are available;
# g = the eater can choose; q = can choose either kind.
models = []
for d, v, g, q in itertools.product((False, True), repeat=4):
    # The statement "can choose either kind" entails availability and agency.
    if q and not (v and g):
        continue
    models.append({"d": d, "v": v, "g": g, "q": q})

def required_condition(m):
    return m["v"] and m["g"]

candidates = {
    "A": lambda m: m["d"],
    "B": lambda m: m["v"],
    "C": lambda m: m["q"],
}

counterexamples = {
    letter: sum(test(m) and not required_condition(m) for m in models)
    for letter, test in candidates.items()
}
answer = [letter for letter, count in counterexamples.items() if count == 0]
assert answer == ["C"]

print(json.dumps({
    "final_answer": answer[0],
    "evidence": {
        "models_enumerated": len(models),
        "candidate_counterexamples": counterexamples
    }
}))
