# Exact finite forward-chaining check for the stated animal domain.
# Negation is represented explicitly; absence of a fact is not negation.

ANIMALS = (
    "bee", "badger", "frog", "snake", "seahorse", "vampire", "swan",
    "beaver", "ostrich", "woodpecker", "monkey", "dove", "rhino",
    "stork", "beetle", "goat", "ant", "dragon", "dinosaur",
    "flamingo", "finch", "pigeon", "king", "peafowl", "emperor",
    "fangtooth", "dragonfly", "zebra", "bison",
)
PRIMARY_COLORS = {"red", "green", "blue"}

def lit(predicate, *args, neg=False):
    return (predicate, tuple(args), neg)

def complement(item):
    predicate, args, neg = item
    return (predicate, args, not neg)

def has(state, predicate, *args, neg=False):
    return lit(predicate, *args, neg=neg) in state

def exists(state, predicate, *args, neg=False):
    return any(has(state, predicate, animal, *args, neg=neg)
               for animal in ANIMALS)

facts = {
    lit("card_color", "bee", "blue"),
    lit("card_color", "frog", "yellow"),
    lit("tears_castle", "bee", "badger", neg=True),
    lit("has_leafy_vegetable", "frog"),
    lit("reduced_hours", "snake"),
    lit("creates_castle", "seahorse", "vampire", neg=True),
}

# Apply the source-domain convention to card colors only.
for animal in ANIMALS:
    for color in PRIMARY_COLORS:
        if has(facts, "card_color", animal, color):
            facts.add(lit("has_primary_card", animal))

# (rule name, conclusion) candidates are generated only when all antecedents
# are present. Existential antecedents are explicitly checked below.
PREFERENCES = {
    ("R11", "R21"),
    ("R16", "R21"),
    ("R15", "R1"),
    ("R24", "R6"),
    ("R3", "R22"),
    ("R8", "R13"),
    ("R9", "R14"),
}

def generate(state):
    out = []

    def emit(rule, conclusion):
        out.append((rule, conclusion))

    # Rule 1
    for a in ANIMALS:
        if has(state, "shouts_at", a, "beaver"):
            emit("R1", lit("unites_with", a, "ostrich"))

    # Rule 2
    if exists(state, "tears_castle", "dove"):
        emit("R2", lit("takes_over", "woodpecker", "emperor", "monkey"))

    # Rule 3
    if exists(state, "persuades", "rhino"):
        emit("R3", lit("shouts_at", "swan", "beaver", neg=True))

    # Rule 4
    if (has(state, "trades_with", "bee", "stork", neg=True)
            and has(state, "trades_with", "beetle", "stork")):
        emit("R4", lit("wants_to_see", "stork", "goat"))

    # Rule 5
    for a in ANIMALS:
        if has(state, "tears_castle", a, "badger", neg=True):
            emit("R5", lit("refuses_to_help", a, "badger"))

    # Rule 6
    if exists(state, "enjoys_companionship", "ant"):
        emit("R6", lit("shouts_at", "swan", "peafowl", neg=True))

    # Rule 7
    if exists(state, "unites_with", "ostrich"):
        emit("R7", lit("trades_with", "beetle", "stork"))

    # Rule 8
    for a in ANIMALS:
        if has(state, "creates_castle", a, "dragon"):
            emit("R8", lit("refuses_to_help", a, "dinosaur"))

    # Rule 9
    if has(state, "smiles_at", "flamingo", "bee"):
        emit("R9", lit("shouts_at", "bee", "beetle"))

    # Rule 10
    if exists(state, "wants_to_see", "goat"):
        emit("R10", lit("captures", "finch", "king", "pigeon", neg=True))

    # Rule 11: no age fact is supplied in the question.
    if has(state, "age_below_four", "frog"):
        emit("R11", lit("destroys_wall", "frog", "swan", neg=True))

    # Rule 12
    for a in ANIMALS:
        if has(state, "creates_castle", a, "vampire", neg=True):
            emit("R12", lit("enjoys_companionship", a, "ant"))

    # Rule 13
    if exists(state, "takes_over", "emperor", "monkey"):
        emit("R13", lit("refuses_to_help", "bee", "dinosaur", neg=True))

    # Rule 14
    for a in ANIMALS:
        if has(state, "wants_to_see", a, "fangtooth"):
            emit("R14", lit("shouts_at", a, "beetle", neg=True))

    # Rule 15
    if exists(state, "trades_with", "bison"):
        emit("R15", lit("unites_with", "swan", "ostrich", neg=True))

    # Rule 16
    if has(state, "has_primary_card", "frog"):
        emit("R16", lit("destroys_wall", "frog", "swan", neg=True))

    # Rule 17
    for a in ANIMALS:
        if has(state, "refuses_to_help", a, "dinosaur", neg=True):
            emit("R17", lit("reveals_secret_to", a, "zebra"))

    # Rule 18
    for a in ANIMALS:
        if (has(state, "shouts_at", a, "beetle", neg=True)
                and has(state, "reveals_secret_to", a, "zebra")):
            emit("R18", lit("trades_with", a, "stork", neg=True))

    # Rule 19
    for a in ANIMALS:
        if has(state, "refuses_to_help", a, "badger"):
            emit("R19", lit("shouts_at", a, "dragonfly"))

    # Rule 20
    for a in ANIMALS:
        if has(state, "shouts_at", a, "dragonfly"):
            emit("R20", lit("wants_to_see", a, "fangtooth"))

    # Rule 21
    if has(state, "has_leafy_vegetable", "frog"):
        emit("R21", lit("destroys_wall", "frog", "swan"))

    # Rule 22
    for a in ANIMALS:
        if has(state, "shouts_at", a, "peafowl"):
            emit("R22", lit("shouts_at", a, "beaver"))

    # Rule 23
    if has(state, "reduced_hours", "snake"):
        emit("R23", lit("tears_castle", "snake", "dove"))

    # Rule 24
    if has(state, "destroys_wall", "frog", "swan"):
        emit("R24", lit("shouts_at", "swan", "peafowl"))

    return out

def resolve(candidates):
    # Suppress a conclusion only when a preferred rule is also applicable
    # and derives its literal's explicit complement.
    accepted = []
    for rule, conclusion in candidates:
        defeated = any(
            (higher, rule) in PREFERENCES
            and other_conclusion == complement(conclusion)
            for higher, other_conclusion in candidates
        )
        if not defeated:
            accepted.append(conclusion)
    return set(accepted)

# Recompute rule conclusions until stable, retaining the supplied facts.
state = set(facts)
seen = set()
stable = False

for _ in range(100):
    frozen = frozenset(state)
    if frozen in seen:
        break
    seen.add(frozen)
    next_state = facts | resolve(generate(state))
    if next_state == state:
        stable = True
        break
    state = next_state

target = lit("captures", "finch", "king", "pigeon")
opposite = complement(target)

if not stable:
    print("UNSUPPORTED: inference did not reach a stable state.")
    print("CHECK UNKNOWN")
else:
    positive = target in state
    negative = opposite in state

    print("stork wants to see the goat:", 
          has(state, "wants_to_see", "stork", "goat"))
    print("finch does not capture the king of the pigeon:", negative)
    print("finch captures the king of the pigeon:", positive)

    if negative and not positive:
        result = "disproved"
    elif positive and not negative:
        result = "proved"
    else:
        result = "unknown"

    print("Expected result:", result)
    print("Submitted answer: disproved")
    print("CHECK PASS" if result == "disproved" else "CHECK FAIL")
