import itertools
import json

# Adjective categories and precedence constraints read from the givens.
CATEGORIES = (
    "opinion", "size", "shape", "age",
    "color", "origin", "material", "purpose",
)
EDGES = (
    ("material", "origin"),  # plastic egyptian; wood chinese; etc.
    ("origin", "age"),       # turkish old green
    ("age", "color"),        # turkish old green
    ("age", "purpose"),      # ancient exercise; old-fashioned typing; etc.
    ("purpose", "opinion"),  # cardboard typing lovely
    ("opinion", "color"),    # silly violet; lovely aqua; etc.
    ("size", "shape"),       # little square; big triangular; etc.
)

OPTIONS = {
    "A": ("shape", "size", "age", "purpose", "opinion", "color"),
    "B": ("material", "origin", "age", "purpose", "opinion", "color", "size", "shape"),
    "C": ("shape", "age", "purpose", "opinion", "color", "origin", "material"),
    "D": ("age", "purpose", "opinion", "color", "size", "shape"),
    "E": ("material", "origin", "age", "purpose", "opinion", "color"),
    "F": ("material", "origin", "age", "purpose", "opinion", "color", "size"),
    "G": ("size", "shape", "age", "purpose", "opinion", "color"),
    "H": ("origin", "age", "purpose", "opinion", "color", "size", "shape"),
    "I": ("material", "origin", "age", "purpose", "opinion", "color", "shape"),
    "J": ("shape", "size", "age", "purpose", "opinion", "color", "origin"),
}

def answers_for_order(order):
    position = {category: i for i, category in enumerate(order)}
    selected = [
        letter for letter, sequence in OPTIONS.items()
        if all(position[a] < position[b] for a, b in zip(sequence, sequence[1:]))
    ]
    return "".join(selected) if selected else "K"

# Exhaustively enumerate all total category orders consistent with the givens.
answer_sets = {}
consistent_order_count = 0
for order in itertools.permutations(CATEGORIES):
    position = {category: i for i, category in enumerate(order)}
    if not all(position[a] < position[b] for a, b in EDGES):
        continue
    consistent_order_count += 1
    answer = answers_for_order(order)
    answer_sets.setdefault(answer, order)

if len(answer_sets) == 1:
    final_answer = next(iter(answer_sets))
    evidence = {
        "consistent_total_orders": consistent_order_count,
        "distinct_answer_sets": 1,
    }
else:
    final_answer = "UNSUPPORTED"
    evidence = {
        "consistent_total_orders": consistent_order_count,
        "distinct_answer_sets": len(answer_sets),
        "witness_answer_sets": [
            {
                "answers": answer,
                "category_order": list(order),
            }
            for answer, order in list(answer_sets.items())[:2]
        ],
    }

print(json.dumps({"final_answer": final_answer, "evidence": evidence}))
