# Exact arithmetic in Q(sqrt(39)).
class Q39:
    def __init__(self, a=0, b=0):
        if isinstance(a, Q39):
            self.a, self.b = a.a, a.b
        else:
            self.a, self.b = F(a), F(b)

    def __add__(self, other):
        other = Q39(other)
        return Q39(self.a + other.a, self.b + other.b)

    __radd__ = __add__

    def __neg__(self):
        return Q39(-self.a, -self.b)

    def __sub__(self, other):
        return self + (-Q39(other))

    def __rsub__(self, other):
        return Q39(other) - self

    def __mul__(self, other):
        other = Q39(other)
        return Q39(self.a * other.a + 39 * self.b * other.b,
                   self.a * other.b + self.b * other.a)

    __rmul__ = __mul__

    def __truediv__(self, other):
        other = Q39(other)
        norm = other.a * other.a - 39 * other.b * other.b
        assert norm != 0
        return Q39((self.a * other.a - 39 * self.b * other.b) / norm,
                   (self.b * other.a - self.a * other.b) / norm)

    def __eq__(self, other):
        other = Q39(other)
        return self.a == other.a and self.b == other.b

    def __float__(self):
        return float(self.a) + float(self.b) * sqrt(39)

    def __str__(self):
        return f"({self.a}) + ({self.b})*sqrt(39)"

