        v = sub(poly[(i + 1) % n], poly[i])
        cosines.append(dot(u, v) / (norm(u) * norm(v)))
    return max(cosines) - min(cosines) <= 1e-5


found = set()
witnesses = {i: [] for i in range(1, 11)}
seen_polygons = set()

for cyc in cycles:
    raw = [coords[i] for i in cyc]
    poly = simplify(raw)
    n = len(poly)
    if n < 3 or abs(area2(poly)) < 1e-8:
        continue

    # Canonicalize the simplified polygon to avoid counting it more than once.
    rounded = tuple(vertex_key(p) for p in poly)
    rev = tuple(reversed(rounded))
    forms = []
    for seq in (rounded, rev):
        forms.extend(seq[k:] + seq[:k] for k in range(n))
    key = min(forms)
    if key in seen_polygons:
        continue
    seen_polygons.add(key)

    # Determine convexity from the signed turns.
    turns = []
    for i in range(n):
        turns.append(cross(sub(poly[(i + 1) % n], poly[i]),
                           sub(poly[(i + 2) % n], poly[(i + 1) % n])))
    convex = all(t >= -1e-7 for t in turns) or all(t <= 1e-7 for t in turns)
    if has_diagonal(poly):
        continue

    category = None
    if n == 3:
        category = 4 if is_right(poly) else 3
    elif n == 4:
        p0, p1, p2, p3 = poly
        pairs = (parallel(p0, p1, p2, p3),
                 parallel(p1, p2, p3, p0))
        if all(pairs):
            if is_right(poly):
                lengths = [norm(sub(poly[(i + 1) % 4], poly[i]))
                           for i in range(4)]
                category = 2 if max(lengths) - min(lengths) <= 1e-5 else 1
            else:
                category = 5
        elif sum(pairs) == 1:
            category = 6
    elif n == 5:
        if convex:
            category = 9 if is_regular(poly) else 7
        else:
            category = 8
    elif n == 6 and convex and is_regular(poly):
        category = 10

    if category is not None:
        found.add(category)
        if len(witnesses[category]) < 2:
            witnesses[category].append(poly)


options = {
    "A": {1, 7, 3}, "B": {1, 8}, "C": {7, 9}, "D": {5},
    "E": {1, 5, 7, 8}, "F": {1, 5, 7, 8, 4, 6},
    "G": {7, 8, 2, 10}, "H": {1, 8, 9}, "I": {5, 3},
    "J": {1}, "K": {7, 8}, "L": {5, 8}, "M": {5, 2},
    "N": {1, 8, 2, 4, 9}, "O": {1, 5, 7, 8, 10},
    "P": {1, 7, 8, 6},
}
claimed = "E"

print("Parsed line segments:", len(segments))
print("Enumerated simple cycles:", len(cycles))
print("Detected shape numbers:", sorted(found))
for number in sorted(found):
    print("Shape", number, "witness:", witnesses[number][0])
print("Claimed option", claimed, "contains:", sorted(options[claimed]))
print("CHECK PASS" if found == options[claimed] else "CHECK FAIL")
