import json

sequence = "( { < { ( ( { } ) ( ) ) } { } < { } > < > > } { } ( { ( { { } } ) [ ( ) ] } ) ) [ ( [ ]"
matching = {")": "(", "}": "{", ">": "<", "]": "["}
