import json

def all_subsets(n):
    return [
        {i for i in range(n) if mask & (1 << i)}
        for mask in range(1 << n)
    ]

def exists_left_not_right(left, right, n):
    return any(i in left and i not in right for i in range(n))

def check_implication(premise, conclusion, n):
    subsets = all_subsets(n)
    for left in subsets:
        for right in subsets:
            if premise(left, right, n) and not conclusion(left, right, n):
                return False, {
                    "left": sorted(left),
                    "right": sorted(right),
                }
    return True, None

def premise_form(left, right, n):
    return exists_left_not_right(left, right, n)

def conclusion_form(left, right, n):
    return exists_left_not_right(right, left, n)

# Exhaustively enumerate interpretations over nonempty universes of sizes 1 and 2.
results = {}
counterexamples = {}
original_valid = True
for n in (1, 2):
    valid, witness = check_implication(premise_form, conclusion_form, n)
    if not valid:
        original_valid = False
        counterexamples["original"] = {"n": n, **witness}
        break

for option in ("A", "C", "D"):
    valid = True
    witness = None
    for n in (1, 2):
        valid, witness = check_implication(premise_form, conclusion_form, n)
        if not valid:
            counterexamples[option] = {"n": n, **witness}
            break
    results[option] = valid

# “Some people are not selfish” and “people are not all selfish”
# have identical truth conditions on a nonempty universe.
b_valid = True
b_witness = None
for n in (1, 2):
    for selfish in all_subsets(n):
        premise = any(i not in selfish for i in range(n))
        conclusion = not all(i in selfish for i in range(n))
        if premise and not conclusion:
            b_valid = False
            b_witness = {"n": n, "selfish": sorted(selfish)}
            break
    if not b_valid:
        break
results["B"] = b_valid
if b_witness is not None:
    counterexamples["B"] = b_witness

invalid = [option for option in ("A", "B", "C", "D") if not results[option]]
answer = ", ".join(invalid)
if len(invalid) > 1:
    answer += " (the question has no unique option)"

print(json.dumps({
    "final_answer": answer,
    "evidence": {
        "original_argument_valid": original_valid,
        "option_validity": results,
        "counterexamples": counterexamples
    }
}))
