# Each object is represented by (A, B), the truth values of two predicates.
# The shared invalid inference is:
#   some A and not B  ->  some B and not A
def premise(model):
    return any(a and not b for a, b in model)

def conclusion(model):
    return any(b and not a for a, b in model)

models = [
    tuple(assignment)
    for n in (1, 2)
    for assignment in product(list(product((False, True), repeat=2)), repeat=n)
]

counterexample = next(
    (m for m in models if premise(m) and not conclusion(m)), None
)
print("Shared-form counterexample (A, B):", counterexample)
print("Original inference valid:", counterexample is None)

# A, C, and D have the same existential form under their ordinary readings.
invalid_options = {
    option for option in ("A", "C", "D")
    if any(premise(m) and not conclusion(m) for m in models)
}

# B says exactly the same thing in premise and conclusion:
# "some people are not selfish" == "not all people are selfish".
b_equivalent_for_all_tested_models = all(
    any(not selfish for selfish in (a for a, _ in m))
    == not all(a for a, _ in m)
    for m in models
)
# Check B directly with one truth value per person.
b_equivalent_for_all_tested_models = all(
    any(not x for x in xs) == (not all(xs))
    for n in (1, 2)
    for xs in product((False, True), repeat=n)
)

print("Invalid options by counterexample:", sorted(invalid_options))
print("B premise/conclusion equivalent:", b_equivalent_for_all_tested_models)
print("Submitted C is an invalid inference:", "C" in invalid_options)

if "C" in invalid_options and len(invalid_options) == 1:
    print("CHECK PASS")
else:
    print("CHECK FAIL: C is invalid, but A and D are invalid by the same form too.")
