from itertools import permutations

# Model each resident as speaking their native language plus the languages
# explicitly mentioned. Rooms are in a line, so only adjacent room numbers
# count as neighbors; communication is possible when residents share a language.
KOREAN = "South Korea"
FRENCH = "France"
BRITISH = "Britain"
GERMAN = "Germany"

languages = {
    KOREAN: {"Korean"},
    FRENCH: {"French", "German"},
    BRITISH: {"English", "Korean"},
    GERMAN: {"Korean", "French", "English", "German"},
}
nationalities = (KOREAN, FRENCH, BRITISH, GERMAN)


def neighbors(order, room_index):
    return [
        order[i]
        for i in (room_index - 1, room_index + 1)
        if 0 <= i < len(order)
    ]


def can_communicate(person_a, person_b):
    return bool(languages[person_a] & languages[person_b])


def check_order(order):
    room = {person: i + 1 for i, person in enumerate(order)}
    korean_neighbors = neighbors(order, room[KOREAN] - 1)
    french_neighbors = neighbors(order, room[FRENCH] - 1)
    british_neighbors = neighbors(order, room[BRITISH] - 1)

    checks = {
        "Korean room number is larger than German's":
            room[KOREAN] > room[GERMAN],
        "Korean cannot communicate with any neighbor":
            not any(can_communicate(KOREAN, n) for n in korean_neighbors),
        "French cannot communicate with any neighbor":
            not any(can_communicate(FRENCH, n) for n in french_neighbors),
        "Briton can communicate with exactly one neighbor":
            sum(can_communicate(BRITISH, n) for n in british_neighbors) == 1,
    }
    return checks


valid_orders = []
for order in permutations(nationalities):
    checks = check_order(order)
    if all(checks.values()):
        valid_orders.append(order)

options = {
    "A": (BRITISH, GERMAN, KOREAN, FRENCH),
    "B": (FRENCH, BRITISH, GERMAN, KOREAN),
    "C": (GERMAN, BRITISH, FRENCH, KOREAN),
    "D": (GERMAN, BRITISH, KOREAN, FRENCH),
}
submitted = "D"

print("Arrangements exhaustively checked:", 24)
print("Valid room orders:", len(valid_orders))
for order in valid_orders:
    print("Valid order, rooms 1 to 4:", ", ".join(order))

submitted_order = options[submitted]
submitted_checks = check_order(submitted_order)
print("Submitted option:", submitted, "-", ", ".join(submitted_order))
print("Submitted option satisfies all clues:", all(submitted_checks.values()))
for clue, passed in submitted_checks.items():
    if not passed:
        print("Failed clue:", clue)

matching_options = [
    label for label, order in options.items()
    if order in valid_orders
]
print("Option matching the exhaustive result:", matching_options)

if len(valid_orders) == 1 and matching_options == [submitted]:
    print("CHECK PASS")
elif len(valid_orders) == 1 and len(matching_options) == 1:
    print("CHECK FAIL")
else:
    print("CHECK UNKNOWN")
